class RangeSet:
    """A normalized set of half-open integer ranges [start, end)."""

    def __init__(self, ranges=()):
        pairs = []
        for start, end in ranges:
            self._check_endpoints(start, end)
            pairs.append((start, end))
        self._ranges = self._normalize(pairs)

    @staticmethod
    def _check_endpoints(start, end):
        if type(start) is not int or type(end) is not int:
            raise TypeError("endpoints must be of exact type int")
        if start > end:
            raise ValueError("start must be <= end")

    @staticmethod
    def _normalize(intervals):
        merged = []
        for a, b in sorted(intervals):
            if b <= a:
                continue
            if merged and a <= merged[-1][1]:
                prev_a, prev_b = merged[-1]
                merged[-1] = (prev_a, max(prev_b, b))
            else:
                merged.append((a, b))
        return merged

    def ranges(self):
        return [tuple(r) for r in self._ranges]

    def add(self, start, end):
        self._check_endpoints(start, end)
        if start >= end:
            return
        self._ranges = self._normalize(self._ranges + [(start, end)])

    def remove(self, start, end):
        self._check_endpoints(start, end)
        if start >= end:
            return
        pieces = []
        for a, b in self._ranges:
            if b <= start or a >= end:
                pieces.append((a, b))
                continue
            if a < start:
                pieces.append((a, start))
            if end < b:
                pieces.append((end, b))
        self._ranges = self._normalize(pieces)

    def contains(self, point):
        if type(point) is not int:
            raise TypeError("point must be of exact type int")
        for a, b in self._ranges:
            if a <= point < b:
                return True
            if point < a:
                break
        return False

    def clip(self, start, end):
        self._check_endpoints(start, end)
        if start >= end:
            return []
        return self._normalize(
            (max(a, start), min(b, end))
            for a, b in self._ranges
            if a < end and b > start
        )

